dosya.icerik:
#!/bin/sh
set -e
# operasyon gunluk ozeti
gun=${1:-$(date +%Y%m%d)}
out=/data/giden/operasyon_${gun}.txt
t=$(mktemp -p /data/tmp) || { echo "gecici dosya olusturulamadi"; exit 4; }
echo "operasyon ${gun} satir=$(ls /data/giden | wc -l)" > "$t"
mv "$t" "$out"; chmod 644 "$out"
echo "uretildi: $out"

